import{_ as n,o as a,c as p,a2 as t}from"./chunks/framework.C4u7U0Dw.js";const d=JSON.parse('{"title":"自媒体与内容创作提示词模板","description":"自媒体与内容创作的 5 条提示词模板：选题库、口播稿、一稿多平台改写、评论区回复、数据复盘。","frontmatter":{"title":"自媒体与内容创作提示词模板","description":"自媒体与内容创作的 5 条提示词模板：选题库、口播稿、一稿多平台改写、评论区回复、数据复盘。"},"headers":[],"relativePath":"community/prompts/自媒体与内容创作.md","filePath":"community/prompts/自媒体与内容创作.md"}'),e={name:"community/prompts/自媒体与内容创作.md"};function l(o,s,i,c,r,u){return a(),p("div",null,[...s[0]||(s[0]=[t(`<h1 id="🎬-自媒体与内容创作-·-5-条提示词模板" tabindex="-1">🎬 自媒体与内容创作 · 5 条提示词模板 <a class="header-anchor" href="#🎬-自媒体与内容创作-·-5-条提示词模板" aria-label="Permalink to &quot;🎬 自媒体与内容创作 · 5 条提示词模板&quot;">​</a></h1><blockquote><p>做内容的人最容易卡在三件事上：<strong>不知道拍什么、写出来不像人话、数据不好不知道为什么。</strong> 这三件事，都能靠&quot;结构化&quot;解决。</p></blockquote><h2 id="本行三句话骨架" tabindex="-1">本行三句话骨架 <a class="header-anchor" href="#本行三句话骨架" aria-label="Permalink to &quot;本行三句话骨架&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我做的是【什么内容 / 什么平台 / 什么人群】，我的身份是【…】。</span></span>
<span class="line"><span>帮我产出【选题 / 口播稿 / 文案】，数量【…】，长度【…】。</span></span>
<span class="line"><span>风格按【我的样例 / 平台调性】来；数据和事例只能来自我给的真实经历，不许编。</span></span></code></pre></div><hr><h2 id="_1-·-选题库-从-你本来就会的东西-里长出来" tabindex="-1">1 · 选题库（从&quot;你本来就会的东西&quot;里长出来） <a class="header-anchor" href="#_1-·-选题库-从-你本来就会的东西-里长出来" aria-label="Permalink to &quot;1 · 选题库（从&quot;你本来就会的东西&quot;里长出来）&quot;">​</a></h2><p><strong>什么时候用</strong>：坐在那儿想选题，想到的都是别人拍过的。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我是谁：【职业 / 经历 / 擅长什么 / 干过什么别人不太知道的事】</span></span>
<span class="line"><span>我的账号定位：【内容方向 / 目标人群 / 我能持续供给什么】</span></span>
<span class="line"><span>我已经发过的（避免重复）：【罗列标题即可】</span></span>
<span class="line"><span>观众最常问我的问题：【…】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我出 30 个选题，按四组分类：</span></span>
<span class="line"><span>① 高流量款（话题性强，谁都想点）——但要和我的定位相关</span></span>
<span class="line"><span>② 高信任款（讲我的专业判断和踩过的坑）</span></span>
<span class="line"><span>③ 高转化款（看完会来找我的那种）</span></span>
<span class="line"><span>④ 长期款（可以做成系列、不担心断更）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>每个选题给：标题 + 一句话说明&quot;这条要讲什么&quot; + 建议形式（口播/图文/教程）</span></span>
<span class="line"><span>规矩：不许编我没经历过的故事；拍不出来的（需要特殊资源）标出来。</span></span></code></pre></div><p><strong>它给你</strong>：30 个选题，分组排好。<strong>&quot;长期款&quot;那一组别忘了——它决定你能不能不断更。</strong></p><hr><h2 id="_2-·-口播稿-3-分钟短视频-说着像人话" tabindex="-1">2 · 口播稿（3 分钟短视频，说着像人话） <a class="header-anchor" href="#_2-·-口播稿-3-分钟短视频-说着像人话" aria-label="Permalink to &quot;2 · 口播稿（3 分钟短视频，说着像人话）&quot;">​</a></h2><p><strong>什么时候用</strong>：文案是写出来了，但念出来像在朗读报告。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这条要讲：【主题 + 核心观点（一句话）】</span></span>
<span class="line"><span>我的真实素材：【我自己的经历 / 我遇到的具体例子，越具体越好】</span></span>
<span class="line"><span>目标观众：【…】，他们现在对这个话题的看法是【…】</span></span>
<span class="line"><span>平台与时长：【抖音/视频号，约 3 分钟】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我写口播稿：</span></span>
<span class="line"><span>① 前 3 秒：一句能让人停下来的话（不要&quot;大家好我是XX&quot;，直接进内容）</span></span>
<span class="line"><span>② 中间：用一个具体场景/故事展开，控制在 500-600 字</span></span>
<span class="line"><span>③ 每 3-4 句给一个&quot;停顿点&quot;（标出来，方便我加停顿和画面）</span></span>
<span class="line"><span>④ 结尾：一个明确的动作引导（关注/评论/私信，只选一个）</span></span>
<span class="line"><span>⑤ 另附：这条稿子的&quot;钩子备选 3 个&quot;（如果第一个效果不好可以换）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要求：</span></span>
<span class="line"><span>- 全部用口语短句，不许出现书面语连接词（&quot;因此&quot;&quot;综上所述&quot;）</span></span>
<span class="line"><span>- 每句话不超过 25 字，方便一口气念完</span></span>
<span class="line"><span>- 不许编数据、不许编案例，只能用我给的素材</span></span></code></pre></div><p><strong>它给你</strong>：一份能直接念的稿 + 3 个备选钩子。<strong>&quot;每句不超过 25 字&quot;是让它说人话的关键指令。</strong></p><hr><h2 id="_3-·-一稿多平台改写-公众号-→-小红书-→-视频号" tabindex="-1">3 · 一稿多平台改写（公众号 → 小红书 → 视频号） <a class="header-anchor" href="#_3-·-一稿多平台改写-公众号-→-小红书-→-视频号" aria-label="Permalink to &quot;3 · 一稿多平台改写（公众号 → 小红书 → 视频号）&quot;">​</a></h2><p><strong>什么时候用</strong>：同一条内容要在三个平台发，一个个改太慢，直接搬又水土不服。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我的原稿（公众号长文 / 或者直接给我要点）：</span></span>
<span class="line"><span>【粘贴原文】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我改写成三个平台版本：</span></span>
<span class="line"><span>① 小红书：标题 3 个（带 emoji，20 字内）+ 正文 300 字（分点，每点一行，口语）+ 5 个话题标签</span></span>
<span class="line"><span>② 视频号/抖音口播：400 字，口语，前 3 秒钩子，结尾一个动作</span></span>
<span class="line"><span>③ 公众号：保留原文骨架，但把开头 200 字重写成&quot;更抓人&quot;的版本，并给 3 个新标题</span></span>
<span class="line"><span></span></span>
<span class="line"><span>每个版本都标注：这个平台的人看到这条，第一反应是什么。</span></span>
<span class="line"><span>规矩：不许增加我原文里没有的事实和数据；平台风格可以变，事实不能变。</span></span></code></pre></div><p><strong>它给你</strong>：同一内容的三份成品 + 平台视角提示。</p><hr><h2 id="_4-·-评论区回复-含-杠精-应对" tabindex="-1">4 · 评论区回复（含&quot;杠精&quot;应对） <a class="header-anchor" href="#_4-·-评论区回复-含-杠精-应对" aria-label="Permalink to &quot;4 · 评论区回复（含&quot;杠精&quot;应对）&quot;">​</a></h2><p><strong>什么时候用</strong>：评论区问你问题、抬杠、或者要资料，一个个回复很费时间，回不好还掉粉。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我这条内容讲了：【…】</span></span>
<span class="line"><span>这条评论：【粘贴原话】</span></span>
<span class="line"><span>这个人的情况（我能看出来的）：【…】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我写回复，三种类型各给一套：</span></span>
<span class="line"><span>① 认真提问型：给到&quot;有用但不超过 2 句&quot;的回答，并留一个钩子</span></span>
<span class="line"><span>② 抬杠/质疑型：不激怒、不认错到没立场，用&quot;你提到的这一点我补充一下&quot;的句式</span></span>
<span class="line"><span>③ 求资源/求联系方式型：给一个不违规、也能筛选出真实需求的回复</span></span>
<span class="line"><span></span></span>
<span class="line"><span>另外给我：</span></span>
<span class="line"><span>- 一句&quot;统一回复模板&quot;（针对反复出现的问题）</span></span>
<span class="line"><span>- 一个&quot;这条评论值不值得置顶&quot;的判断标准</span></span>
<span class="line"><span>规矩：不删差评、不对骂；不许承诺我做不到的事；涉及专业问题的回答必须是我确认过的内容。</span></span></code></pre></div><p><strong>它给你</strong>：三套回复 + 统一模板。<strong>遇到专业提问，&quot;我确认过再答&quot;永远比抢答好。</strong></p><hr><h2 id="_5-·-数据复盘-这条为什么好-为什么差" tabindex="-1">5 · 数据复盘（这条为什么好 / 为什么差） <a class="header-anchor" href="#_5-·-数据复盘-这条为什么好-为什么差" aria-label="Permalink to &quot;5 · 数据复盘（这条为什么好 / 为什么差）&quot;">​</a></h2><p><strong>什么时候用</strong>：数据出来了，只知道&quot;这条爆了&quot;，但不知道为什么爆，下次复制不出来。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这条内容的数据：</span></span>
<span class="line"><span>- 平台 / 发布时间 / 形式（口播/图文/教程）</span></span>
<span class="line"><span>- 播放量 / 完播率 / 点赞 / 评论 / 转发 / 涨粉 / 私信数：【…（有的都写）】</span></span>
<span class="line"><span>- 同账号近 10 条的同类数据（我的平均水平）：【…】</span></span>
<span class="line"><span>- 这一条内容本身：标题、开头前 3 秒、正文结构、结尾动作</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我：</span></span>
<span class="line"><span>① 判断这条相对我的平均水平是&quot;高于/持平/低于&quot;，高多少</span></span>
<span class="line"><span>② 找出 3 个可能的差异点（标题？开头？话题？发布时间？），并说明每个差异点的证据强弱</span></span>
<span class="line"><span>③ 把我这 10 条按数据排序，看有没有规律（哪类选题普遍更好）</span></span>
<span class="line"><span>④ 给下一个内容的具体动作：这条的经验，下一篇怎么用</span></span>
<span class="line"><span>规矩：数据只能用我给的；不许编行业基准值（&quot;行业平均完播率 30%&quot;这种）；结论证据不足时就写&quot;证据不足&quot;。</span></span></code></pre></div><p><strong>它给你</strong>：复盘结论 + 下一篇的具体动作。<strong>&quot;不许编行业基准值&quot;很重要</strong>——很多 AI 会随口给你一个假基准。</p><hr><h2 id="⚠️-这一行的三条提醒" tabindex="-1">⚠️ 这一行的三条提醒 <a class="header-anchor" href="#⚠️-这一行的三条提醒" aria-label="Permalink to &quot;⚠️ 这一行的三条提醒&quot;">​</a></h2><ol><li><strong>别让 AI 编你的故事</strong>：它会很自然地替你加一句&quot;我有个朋友……&quot;。所有事例必须是你真实经历的，加一句&quot;不许编&quot;在提示词里。</li><li><strong>别让它替你立人设</strong>：人设是长期行为的产物，AI 只能帮你表达，替不了你判断。</li><li><strong>平台规则自己查</strong>：引流话术、违禁词、医疗财经类内容限制——不同平台、不同时间都不一样，AI 给的是通用做法。</li></ol><hr><p><strong>目录</strong>：<a href="/MoMAWork-/community/prompts/">← 回到行业提示词模板库</a> ｜ 下一个行业 → <strong><a href="/MoMAWork-/community/prompts/技术与研发.html">技术与研发</a></strong></p>`,34)])])}const g=n(e,[["render",l]]);export{d as __pageData,g as default};
